#include "HealthComponent.h"

void UHealthComponent::BeginPlay()
{
	Super::BeginPlay();
	CurrentHealth = MaxHealth;
}

bool UHealthComponent::ApplyDamage(float Amount)
{
	if (Amount <= 0.f || bIsDead)
	{
		return false;
	}

	const float PreviousHealth = CurrentHealth;
	CurrentHealth = FMath::Max(0.f, CurrentHealth - Amount);
	OnHealthChanged.Broadcast(CurrentHealth, CurrentHealth - PreviousHealth);

	if (CurrentHealth <= 0.f)
	{
		bIsDead = true;
		OnDeath.Broadcast();
	}
	return true;
}

bool UHealthComponent::Heal(float Amount)
{
	if (Amount <= 0.f || bIsDead || CurrentHealth >= MaxHealth)
	{
		return false;
	}

	const float PreviousHealth = CurrentHealth;
	CurrentHealth = FMath::Min(MaxHealth, CurrentHealth + Amount);
	OnHealthChanged.Broadcast(CurrentHealth, CurrentHealth - PreviousHealth);
	return true;
}

bool UHealthComponent::IsDead() const
{
	return bIsDead;
}

#pragma once

#include "CoreMinimal.h"
#include "Components/ActorComponent.h"
#include "Config/ArenaBalance.h"
#include "HealthComponent.generated.h"

/** Notifica un cambio de vida. Delta es negativo con daño y positivo con curación. */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_TwoParams(FOnHealthChanged, float, NewHealth, float, Delta);

/** Notifica la muerte del componente. Se emite una sola vez. */
DECLARE_DYNAMIC_MULTICAST_DELEGATE(FOnDeath);

/** Componente de vida reutilizable para personajes y enemigos del modo Arena. */
UCLASS(ClassGroup = (Arena), meta = (BlueprintSpawnableComponent))
class ARENA_API UHealthComponent : public UActorComponent
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;

	/** Vida máxima. Por defecto, el valor vigente de balance. */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Arena")
	float MaxHealth = ArenaBalance::DefaultMaxHealth;

	/** Vida actual. */
	UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category = "Arena")
	float CurrentHealth = 0.f;

	/** Se emite cada vez que cambia la vida. */
	UPROPERTY(BlueprintAssignable, Category = "Arena")
	FOnHealthChanged OnHealthChanged;

	/** Se emite una sola vez, al llegar la vida a 0. */
	UPROPERTY(BlueprintAssignable, Category = "Arena")
	FOnDeath OnDeath;

	/** Aplica daño. Devuelve false si la cantidad no es positiva o el componente ya murió. */
	UFUNCTION(BlueprintCallable, Category = "Arena")
	bool ApplyDamage(float Amount);

	/** Cura vida. Devuelve false si la cantidad no es positiva, está muerto o la vida ya está llena. */
	UFUNCTION(BlueprintCallable, Category = "Arena")
	bool Heal(float Amount);

	/** Devuelve true cuando la vida llegó a 0. */
	UFUNCTION(BlueprintPure, Category = "Arena")
	bool IsDead() const;

private:
	/** true desde que la vida llega a 0. */
	bool bIsDead = false;
};
